import{_ as a,o as s,c as e,am as l}from"./chunks/framework.CiF4W93w.js";const h=JSON.parse('{"title":"Java并发编程_进阶内容","description":"","frontmatter":{"title":"Java并发编程_进阶内容","excerpt":"Java并发编程_进阶内容","date":"2023-12-08 00:14:54","updated":"2023-12-08 00:14:54"},"headers":[],"relativePath":"基础/多线程并发与JVM原理/Java技术栈_多线程/Java并发编程_进阶内容.md","filePath":"基础/多线程并发与JVM原理/Java技术栈_多线程/Java并发编程_进阶内容.md","lastUpdated":null}'),o={name:"基础/多线程并发与JVM原理/Java技术栈_多线程/Java并发编程_进阶内容.md"};function p(c,n,t,i,r,d){return s(),e("div",null,[...n[0]||(n[0]=[l(`<blockquote><p>大纲</p></blockquote><ul><li>线程模型</li><li>悲观锁</li><li>乐观锁</li><li>ReentrantLock <ul><li>AQS</li><li>CAS</li></ul></li></ul><p><strong>悲观锁和乐观锁</strong></p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202401191517637.png" alt="image.png"></p><h3 id="_1、什么是线程模型" tabindex="-1">1、什么是线程模型？ <a class="header-anchor" href="#_1、什么是线程模型" aria-label="Permalink to &quot;1、什么是线程模型？&quot;">​</a></h3><blockquote><p>先回顾一下线程和进程的区分</p></blockquote><ul><li>进程： <ul><li>一个在内存中运行的应用程序。每个进程都有自己独立的一块内存空间，一个进程可以有多个线程，比如在Windows系统中，一个运行的xx.exe就是一个进程。</li></ul></li><li>线程 <ul><li>进程中的一个执行任务（控制单元），负责当前进程中程序的执行。一个进程至少有一个线程，一个进程可以运行多个线程，多个线程可共享数据。</li><li>与进程不同的是同类的多个线程共享进程的<strong>堆</strong>和<strong>方法区</strong>资源，但每个线程有自己的<strong>程序计数器</strong>、<strong>虚拟机栈</strong>和<strong>本地方法栈</strong>，所以系统在产生一个线程，或是在各个线程之间作切换工作时，负担要比进程小得多，也正因为如此，线程也被称为轻量级进程。</li></ul></li></ul><p><strong>根本区别</strong>：进程是操作系统资源分配的基本单位，而线程是处理器任务调度和执行的基本单位</p><blockquote><p>什么是线程模型</p></blockquote><p>并发编程在计算机中如何实现的，在 Java 开发领域中，JVM线程对不同操作系统上的原生线程进行了高级抽象，使开发者大多数情况下可以不用关注下层细节，而只要专注上层开发。</p><p>JVM线程与操作系统线程之间存在着某种映射关系，这两种<strong>不同维度的线程之间的规范和协议</strong>，就是线程模型。</p><blockquote><p>用户线程和内核线程</p></blockquote><ul><li>用户线程：由用户空间程序管理和调度的线程，运行在用户空间（专门给应用程序使用）。</li><li>内核线程：由操作系统内核管理和调度的线程，运行在内核空间（只有内核程序可以访问）。</li></ul><blockquote><p>线程模型类型</p></blockquote><p>JVM线程模型有三种模型：一对一、多对一、多对多。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202311161619698.png" alt="image.png"></p><p><strong>一对一</strong></p><p>在Jva线程（用户线程）与操作系统线程(KLT)之间建立一对一的关系，简单粗暴，但好用。</p><ul><li>优点： <ul><li>每个线程都是独立的调度单元，直接利用操作系统内核提供的调度功能。</li></ul></li><li>缺点： <ul><li>用户线程的阻塞唤醒，会直接映射到内核线程上，容易<strong>引起频繁切换，降低性</strong>能。但是一些语言引入了CAS来避免一部分的内核调用，比如Java 引入了AQS这种函数级别的锁，<strong>减少使用内核级别的锁</strong>，就能提升性能。</li></ul></li></ul><p>目前大部分主流 JVM 上都是采用的这种线程模型。</p><p><strong>多对一模型</strong></p><ul><li>优点 <ul><li>用户线程的很多操作对内核来说都是透明的，不需要用户态和内核态的频繁切换，使线程的创建、调度、同步等非常快：</li></ul></li><li>缺点 <ul><li>如果其中一个用户线程阻塞，其他用户线程也无法执行</li><li>这种模型下，内核并不知道用户态有哪些线程，调度和优先级等不完整。</li></ul></li></ul><p><strong>多对多模型</strong></p><ul><li>优点：兼具前两者的优点</li><li>缺点：实现复杂</li></ul><p>目前主流语言中，Java 使用的是 一对一线程模型；Go 语言使用的是 多对多线程模型；Python 的 gevent 使用的多对一线程模型。</p><h3 id="_2、悲观锁机制" tabindex="-1">2、悲观锁机制 <a class="header-anchor" href="#_2、悲观锁机制" aria-label="Permalink to &quot;2、悲观锁机制&quot;">​</a></h3><p>在了解悲观锁机制前，我们先来了解一下什么是锁。</p><h4 id="什么是锁" tabindex="-1">什么是锁 <a class="header-anchor" href="#什么是锁" aria-label="Permalink to &quot;什么是锁&quot;">​</a></h4><p>在并发环境下，会出现多个线程对同一个资源进行争抢的情况，假设A线程对资源正在进行修改，此时 B线程此时又对资源进行了修改，这就可能会导致数据不一致的问题。</p><p>为了解决这个问题，引入了锁机制，<strong>通过一种抽象的“锁”来对资源进行锁定</strong>，当一个线程持有“锁”的时候，其他线程必须等待“锁”，本质上是在临界资源上对线程进行一种串行化。</p><h4 id="java语言的锁机制" tabindex="-1">Java语言的锁机制 <a class="header-anchor" href="#java语言的锁机制" aria-label="Permalink to &quot;Java语言的锁机制&quot;">​</a></h4><blockquote><p>Java 虚拟机的内存结构</p></blockquote><p>在了解 Java语言锁机制之前，我们先对简单了解一下 Java 虚拟机的内存结构。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20231116222015.png" alt="image.png"></p><p>JVM 运行时内存结构主要包含了五个部分：</p><ul><li>程序计数器(PC寄存器)、</li><li>JVM栈、</li><li>Native方法栈、</li><li>堆、</li><li>方法区。</li></ul><p>上图中，红色区域是各个线程私有的。这个区域中的数据，不会出现线程竞争的关系。</p><p>而蓝色区域中的数据被所有线程共享，其中Jva堆中存放的是大量对象，方法区中<strong>存放类信息、常量、静态变 量</strong>等数据。</p><p>当多个线程在竞争其中的一些数据时，可能会发生难以预料的异常情况。在程序开发中，锁的主要应用范围就是在数据共享区域。</p><p>在代码层面，Jvva 主要采用了两种实现方式：</p><ul><li>1.基于Object的悲观锁。</li><li>2.基于CAS的乐观锁。</li></ul><p>本章主要讲解基于Object的悲观锁。</p><blockquote><p>悲观锁机制</p></blockquote><p>悲观锁总是假设最坏的情况，认为共享资源<strong>每次被访问的时候就会出现问题</strong>(比如共享数据被修改)，所以每次在获取资源操作的时候都会上锁，这样其他线程想拿到这个资源就会阻塞直到锁被上一个持有者释放。</p><p>也就是说，<strong>共享资源每次只给一个线程使用，其它线程阻塞，用完后再把资源转让给其它线程</strong>。</p><blockquote><p>基于Object的悲观锁</p></blockquote><p>在Java中，每个Object,也就是每个对象都拥有一把锁，这把锁存放在对象头中，记录了当前对象被哪个线程占用。</p><blockquote><p>对象和对象头的结构</p></blockquote><p><strong>Java 对象</strong></p><p>Java对象分为三个部分：</p><ul><li>对象头</li><li>实例数据</li><li>对齐填充字节</li></ul><p>其中对齐填充字节是为了满足“Java对象大小是8字节的倍数”这一条件而设计的，为对象对齐填充了一些无用字节。</p><p>实例数据是在初始化对象时设定的属性和状态等内容。</p><p><strong>对象头</strong></p><p>对象头存放了一些对象本身的运行时信息。对象头包含了两部分：</p><ul><li>Mark Word</li><li>Class Pointer</li></ul><p>相较于实例数据，对象头属于一些额外的存储开销，它被设计得极小（一般为232bt或264bt) 来提升效率。</p><p>Class Pointer是一个指针，指向当前对象类型所在方法区中的Class信息；</p><p>Mark Word 存储了<strong>很多当前对象的运行时状态信息</strong>，比如 HashCode.、锁状态标志、指向锁记录的指针、偏向线程 ID、锁标志位等等。</p><p>可以通过下面这张表对 Mark Word有一个更直观的认识：</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20231116223405.png" alt="image.png"></p><p>“锁”的信息存储在对象头的Mark Word中。Mark Word 的最后两位，代表锁标志位，分别对应“无锁”、“偏向锁”、“轻量级锁”、“重量级锁”四种状态。</p><p>在Java中，启用对象锁的方式是使用<code>synchronized</code>关键字。</p><h4 id="对象锁的四种状态" tabindex="-1">对象锁的四种状态 <a class="header-anchor" href="#对象锁的四种状态" aria-label="Permalink to &quot;对象锁的四种状态&quot;">​</a></h4><p>锁主要存在四种状态，依次是：无锁状态、偏向锁状态、轻量级锁状态、重量级锁状态，他们会随着竞争的激烈而逐渐升级。</p><p>锁可以升级不可降级，这种策略是为了提高获得锁和释放锁的效率</p><h3 id="_3、乐观锁机制" tabindex="-1">3、乐观锁机制 <a class="header-anchor" href="#_3、乐观锁机制" aria-label="Permalink to &quot;3、乐观锁机制&quot;">​</a></h3><p>乐观锁：乐观锁总是假设最好的情况，即不会去考虑别的线程修改数据，所以不会上锁，但是在更新的时候会判断在此期间别的线程有没有去更新这个数据。</p><p>Java 中的乐观锁一般是<strong>基于 CAS 原语 来</strong>进行的（如<code>AtomicInteger</code>）；而CAS 是一种原语操作，他也用于了悲观锁中 ReentrantLock 的锁状态管理。</p><hr><p>在多个线程对于同一个资源进行访问的访问，互斥锁的方式是悲观的，在线程访问的时候，互斥锁会锁定资源，<strong>只供一个线程调用，而阻塞其他线程</strong>，让其他线程等待。</p><p>在一些情况下，同步代码块执行的耗时远远小于线程切换的耗时，这种情况下使用互斥锁对性能是不太划算的。在这种场景下，直接在用户态对线程的切换进行管理，效率更高。实际操作的时候是通过每次使用同步原语对共享资源进行锁定，让线程反复“乐观”地去尝试获取共享资源，如果发现空闲，那么使用，如果被占用，那么继续“乐观”地重试。</p><blockquote><p>乐观锁和悲观锁 <img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20231207231904.png" alt="image.png"></p></blockquote><blockquote><p>CAS</p></blockquote><p>在 Java 中，实现这种同步原语的算法是 CAS (Compare And Swap)。</p><p>简单翻译是：比较然后交换</p><p>CAS操作包含三个操作数：内存位置（要更新的变量）、预期原值和新值。</p><p><strong>工作原理</strong></p><ol><li><strong>检查和更新</strong>： <ul><li>CAS首先检查<strong>目标内存位置的当前值</strong>是否与预期原值相同。如果相同，它会将该内存位置的值更新为新值。</li><li>如果目标值已被其他线程改变（不等于预期原值），CAS操作失败。</li></ul></li><li><strong>无锁操作</strong>： <ul><li>CAS提供了一种无需锁定的方式来实现并发控制，减少了锁的开销和复杂性。</li></ul></li></ol><div style="border:1px solid #999;border-radius:5px;padding:10px;"> CAS操作是原子性的。 </div><h3 id="_4、悲观锁和乐观锁" tabindex="-1">4、悲观锁和乐观锁 <a class="header-anchor" href="#_4、悲观锁和乐观锁" aria-label="Permalink to &quot;4、悲观锁和乐观锁&quot;">​</a></h3><h4 id="悲观锁示例" tabindex="-1">悲观锁示例 <a class="header-anchor" href="#悲观锁示例" aria-label="Permalink to &quot;悲观锁示例&quot;">​</a></h4><p>在Java中，悲观锁通常是通过<code>synchronized</code>关键字或<code>ReentrantLock</code>类实现的。</p><p><code>synchronized</code> 使用示例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>public class PessimisticLockExample {</span></span>
<span class="line"><span>    private int count = 0;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    public synchronized void increment() {</span></span>
<span class="line"><span>        count++;  // 仅当持有对象锁时，才能执行此操作</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    public synchronized int getCount() {</span></span>
<span class="line"><span>        return count;  // 同样，需要持有对象锁才能执行</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>在这个例子中，我们用<code>synchronized</code>关键字锁定了整个方法。</p><p>当一个线程进入<code>increment</code>或<code>getCount</code>方法时，它必须先获得这个对象的锁。在这段时间内，其他任何试图进入这些同步方法的线程都会被阻塞。</p><h4 id="乐观锁示例" tabindex="-1">乐观锁示例 <a class="header-anchor" href="#乐观锁示例" aria-label="Permalink to &quot;乐观锁示例&quot;">​</a></h4><p>乐观锁通常是通过CAS（比较并交换）操作实现的。</p><p>在Java中，<code>AtomicInteger</code>类提供了一种使用乐观锁的方式。以下是一个使用<code>AtomicInteger</code>实现乐观锁的示例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import java.util.concurrent.atomic.AtomicInteger;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>public class OptimisticLockExample {</span></span>
<span class="line"><span>    private AtomicInteger count = new AtomicInteger(0);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    public void increment() {</span></span>
<span class="line"><span>        int currentValue;</span></span>
<span class="line"><span>        int newValue;</span></span>
<span class="line"><span>        do {</span></span>
<span class="line"><span>            currentValue = count.get(); // 获取当前值</span></span>
<span class="line"><span>            newValue = currentValue + 1; // 计算新值</span></span>
<span class="line"><span>        } while (!count.compareAndSet(currentValue, newValue)); // CAS操作</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    public int getCount() {</span></span>
<span class="line"><span>        return count.get();</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>在这个例子中，<code>AtomicInteger</code>的<code>compareAndSet</code>方法实现了CAS操作。</p><p>它会比较<code>count</code>的当前值和<code>currentValue</code>。如果相同，它会更新<code>count</code>为<code>newValue</code>。这个过程是无锁的，即使在并发环境下也不会阻塞其他线程。如果<code>count</code>的值在此期间被其他线程修改，<code>compareAndSet</code>会返回<code>false</code>，循环继续，直到更新成功。</p><blockquote><p>对比</p></blockquote><ul><li><strong>悲观锁</strong>（<code>synchronized</code>，<code>ReentrantLock</code>）适用于写操作多的场景，因为它防止了多个线程同时写入，减少了冲突。</li><li><strong>乐观锁</strong>（如<code>AtomicInteger</code>的CAS操作）适用于读操作多的场景，它不会阻塞线程，但在写操作频繁的情况下可能会导致高重试成本。</li></ul><h3 id="_5、reentrantlock-☆" tabindex="-1">5、ReentrantLock ☆ <a class="header-anchor" href="#_5、reentrantlock-☆" aria-label="Permalink to &quot;5、ReentrantLock   ☆&quot;">​</a></h3><p>线程考察的一个重点，一个是 <code>synchronized</code>关键字，另外一个就是 <code>ReentrantLock</code>类。</p><p>这句话可以阐述 ReentrantLock 的大部分操作：</p><p><code>ReentrantLock</code> 里面有一个内部类 <code>Sync</code>，<code>Sync</code> 继承 AQS（<code>AbstractQueuedSynchronizer</code>），添加锁和释放锁的大部分操作实际上都是在 <code>Sync</code> 中实现的。<code>Sync</code> 有公平锁 <code>FairSync</code> 和非公平锁 <code>NonfairSync</code> 两个子类。</p><p>建议可以直接看一下“源码解析”这一部分。</p><h4 id="reentrantlock-的基础使用" tabindex="-1">ReentrantLock 的基础使用 <a class="header-anchor" href="#reentrantlock-的基础使用" aria-label="Permalink to &quot;ReentrantLock 的基础使用&quot;">​</a></h4><p>在并发编程中，悲观锁是一种策略，它假设最坏的情况：即在多个线程尝试同时访问共享资源时，会发生冲突。因此，悲观锁在访问任何共享资源之前会先锁定它，以防止其他线程的访问，直到它完成操作并释放锁。</p><blockquote><p>ReentrantLock（可重入锁）</p></blockquote><p><code>ReentrantLock</code> 是一个可重入的互斥锁，它提供了比 <code>synchronized</code> 关键字更高级的功能，如可中断的锁获取操作、公平锁策略、锁绑定多个条件等。</p><blockquote><p>基于 AQS 的实现</p></blockquote><ul><li>AQS 提供了一种管理锁状态的框架，并处理了线程的排队和阻塞。在 <code>ReentrantLock</code> 的实现中，AQS 负责维护一个表示锁状态的变量和一个由等待锁的线程组成的队列。</li><li>当一个线程尝试获取 <code>ReentrantLock</code> 时，AQS 会检查锁的状态，然后要么授予锁（如果当前未被其他线程持有），要么将尝试获取锁的线程放入等待队列。</li></ul><blockquote><p>悲观锁的特性</p></blockquote><ul><li><code>ReentrantLock</code> 作为一种悲观锁，是基于这样的假设：如果不采取措施，多个线程同时修改同一个资源会导致问题。因此，它在修改资源之前先加锁，防止其他线程同时进行写操作。</li><li>这与乐观锁的策略不同，乐观锁允许多个线程进入临界区，但在实际修改数据时检查是否存在冲突。</li></ul><p>示例</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import java.util.concurrent.locks.ReentrantLock;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>public class ReentrantLockExample {</span></span>
<span class="line"><span>    private final ReentrantLock lock = new ReentrantLock();</span></span>
<span class="line"><span>    private int count = 0;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    public void increment() {</span></span>
<span class="line"><span>        lock.lock();  // 获取锁</span></span>
<span class="line"><span>        try {</span></span>
<span class="line"><span>            count++;</span></span>
<span class="line"><span>        } finally {</span></span>
<span class="line"><span>            lock.unlock();  // 释放锁</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    public int getCount() {</span></span>
<span class="line"><span>        return count;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>在这个示例中，我们在修改 <code>count</code> 变量之前获取了锁，并在操作完成后释放了锁。</p><p>这确保了即使多个线程尝试同时调用 <code>increment</code> 方法，<code>count</code> 的增加也是线程安全的。</p><h4 id="reentrantlock-的实现原理" tabindex="-1">ReentrantLock 的实现原理 <a class="header-anchor" href="#reentrantlock-的实现原理" aria-label="Permalink to &quot;ReentrantLock 的实现原理&quot;">​</a></h4><p><code>ReentrantLock</code> 是 Java 并发包中的一个重要组件，基于 AQS 实现。</p><p>基本原理</p><ol><li><strong>可重入性</strong>： <ul><li><code>ReentrantLock</code> 是一个可重入锁。这意味着同一个线程可以多次获取同一个锁而不会发生死锁。这是通过为每个锁维护一个持有计数和一个指向当前持有锁的线程的引用来实现的。</li></ul></li><li><strong>基于 AQS</strong>： <ul><li><code>ReentrantLock</code> 的实现依赖于 AQS。AQS 使用一个整型的 volatile 变量来表示同步状态，并使用一个 FIFO 队列来管理那些等待获取锁的线程。</li></ul></li><li><strong>锁的状态</strong>： <ul><li>在 <code>ReentrantLock</code> 中，锁的状态是由 AQS 的同步状态变量来表示的。状态为 0 表示锁是可用的，状态为 1 表示锁被一个线程持有，大于 1 表示同一个线程重入了这个锁。</li></ul></li><li><strong>获取锁</strong>： <ul><li>当一个线程尝试获取锁时，如果同步状态为 0，AQS 会尝试通过 CAS（比较并交换）操作将状态设置为 1，从而获取锁。</li><li>如果锁已经被其他线程持有（同步状态非 0），那么尝试获取锁的线程会被加入到 AQS 维护的等待队列中。</li></ul></li><li><strong>释放锁</strong>： <ul><li>当线程完成任务后，它会调用 <code>unlock</code> 方法来释放锁。这将减少 AQS 同步状态的计数。当计数降到 0 时，锁被完全释放，等待队列中的下一个线程将有机会获取锁。</li></ul></li></ol><p>公平性和非公平性</p><ul><li><strong>公平锁</strong>：在公平模式下，<code>ReentrantLock</code> 会按照线程在等待队列中的等待顺序来获取锁。这意味着首先进入等待队列的线程将先获得锁。</li><li><strong>非公平锁</strong>：在非公平模式下，当锁可用时，任何请求它的线程都有机会获取锁。这可能不会遵守等待队列中的顺序。</li></ul><p>性能考量</p><ul><li><strong>选择公平性</strong>：公平锁通常会有较低的性能，因为它严格按照等待队列来分配锁，但它可以减少线程饥饿的情况。</li><li><strong>选择非公平性</strong>：非公平锁可能会有更好的性能，但可能导致线程饥饿，因为某些线程可能会长时间等待而不得不频繁地重新调度。</li></ul><p><code>ReentrantLock</code> 提供了一种灵活的锁定机制，通过 AQS 实现了可重入性和可选的公平性。</p><p>它允许更细粒度的锁控制，从而在高度竞争的环境中提供比内置 <code>synchronized</code> 更高的性能和更强的功能。</p><h4 id="源码解析" tabindex="-1">源码解析 <a class="header-anchor" href="#源码解析" aria-label="Permalink to &quot;源码解析&quot;">​</a></h4><h5 id="reentrantlock-类结构" tabindex="-1">ReentrantLock 类结构 <a class="header-anchor" href="#reentrantlock-类结构" aria-label="Permalink to &quot;ReentrantLock 类结构&quot;">​</a></h5><p><code>ReentrantLock</code> 本身是一个相对简单的类，它依赖于内部类 <code>Sync</code> 的实现，而 <code>Sync</code> 是 <code>AbstractQueuedSynchronizer</code> 的子类。</p><p>在 <code>ReentrantLock</code> 中，有两个主要的内部类：<code>FairSync</code> 和 <code>NonfairSync</code>，分别对应公平锁和非公平锁的实现。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>public class ReentrantLock implements Lock, java.io.Serializable {</span></span>
<span class="line"><span>    private final Sync sync;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    abstract static class Sync extends AbstractQueuedSynchronizer {</span></span>
<span class="line"><span>        // ... 实现细节</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    static final class NonfairSync extends Sync {</span></span>
<span class="line"><span>        // ... 非公平锁实现</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    static final class FairSync extends Sync {</span></span>
<span class="line"><span>        // ... 公平锁实现</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    // 构造函数等其他方法</span></span>
<span class="line"><span>}</span></span></code></pre></div><h5 id="sync-类" tabindex="-1">Sync 类 <a class="header-anchor" href="#sync-类" aria-label="Permalink to &quot;Sync 类&quot;">​</a></h5><p><code>Sync</code> 类是 <code>AbstractQueuedSynchronizer</code> 的一个扩展，提供了大部分与锁状态管理相关的功能。</p><p>它使用 AQS 的状态变量来表示锁的持有次数，以及持有锁的线程。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>abstract static class Sync extends AbstractQueuedSynchronizer {</span></span>
<span class="line"><span>    protected final boolean isHeldExclusively() {</span></span>
<span class="line"><span>        return getExclusiveOwnerThread() == Thread.currentThread();</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    final void lock() {</span></span>
<span class="line"><span>        acquire(1);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    // 其他方法，包括 tryAcquire, tryRelease 等</span></span>
<span class="line"><span>}</span></span></code></pre></div><h5 id="公平锁和非公平锁的实现" tabindex="-1">公平锁和非公平锁的实现 <a class="header-anchor" href="#公平锁和非公平锁的实现" aria-label="Permalink to &quot;公平锁和非公平锁的实现&quot;">​</a></h5><p><code>FairSync</code> 和 <code>NonfairSync</code> 类重写了 <code>tryAcquire</code> 方法以提供不同的锁获取策略。</p><ul><li><strong>非公平锁</strong>（<code>NonfairSync</code>）：在尝试获取锁时，会立即尝试改变状态，而不检查等待队列。</li><li><strong>公平锁</strong>（<code>FairSync</code>）：在尝试获取锁之前，会检查等待队列，以确保队列中的线程先获得服务。</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>static final class NonfairSync extends Sync {</span></span>
<span class="line"><span>    protected final boolean tryAcquire(int acquires) {</span></span>
<span class="line"><span>        // 实现非公平的锁获取逻辑</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>static final class FairSync extends Sync {</span></span>
<span class="line"><span>    protected final boolean tryAcquire(int acquires) {</span></span>
<span class="line"><span>        // 实现公平的锁获取逻辑</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><h5 id="abstractqueuedsynchronizer-aqs" tabindex="-1">AbstractQueuedSynchronizer（AQS） <a class="header-anchor" href="#abstractqueuedsynchronizer-aqs" aria-label="Permalink to &quot;AbstractQueuedSynchronizer（AQS）&quot;">​</a></h5><p>AQS 是实现锁和其他同步器的框架。它使用一个 int 类型的 volatile 变量来表示同步状态，并使用一个队列来管理那些未能成功获取同步状态的线程。</p><ul><li><strong>状态管理</strong>：AQS 提供了一系列方法来操作其状态变量，如 <code>getState()</code>, <code>setState(int)</code> 和 <code>compareAndSetState(int, int)</code>。</li><li><strong>队列管理</strong>：AQS 维护了一个等待队列，当线程尝试获取资源失败时，它会被加入到这个队列中。</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>public abstract class AbstractQueuedSynchronizer extends AbstractOwnableSynchronizer implements java.io.Serializable {</span></span>
<span class="line"><span>    private transient volatile Node head;</span></span>
<span class="line"><span>    private transient volatile Node tail;</span></span>
<span class="line"><span>    private volatile int state;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    // 内部类 Node，队列节点的定义</span></span>
<span class="line"><span>    static final class Node {</span></span>
<span class="line"><span>        // Node 的结构和方法</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    // 状态管理和队列操作的方法</span></span>
<span class="line"><span>}</span></span></code></pre></div><h5 id="锁的获取与释放" tabindex="-1">锁的获取与释放 <a class="header-anchor" href="#锁的获取与释放" aria-label="Permalink to &quot;锁的获取与释放&quot;">​</a></h5><ul><li><strong>获取锁</strong>：当 <code>ReentrantLock</code> 的 <code>lock()</code> 方法被调用时，实际上是调用了 <code>Sync</code> 类的 <code>acquire</code> 方法，该方法又会调用 <code>tryAcquire</code> 方法。<code>tryAcquire</code> 的具体实现取决于是 <code>FairSync</code> 还是 <code>NonfairSync</code>。</li><li><strong>释放锁</strong>：<code>unlock()</code> 方法调用 <code>Sync</code> 类的 <code>release</code> 方法，进而调用<code>tryRelease</code> 方法。这个方法会更新同步状态，并在状态变为 0 时（即锁被完全释放时），唤醒等待队列中的线程.</li></ul><h5 id="获取锁的过程" tabindex="-1">获取锁的过程 <a class="header-anchor" href="#获取锁的过程" aria-label="Permalink to &quot;获取锁的过程&quot;">​</a></h5><ol><li>当一个线程调用 <code>lock()</code> 方法时，它实际上调用的是 <code>Sync</code> 类中的 <code>acquire(int)</code> 方法。</li><li><code>acquire(int)</code> 方法会调用重写的 <code>tryAcquire(int)</code> 方法（取决于是 <code>FairSync</code> 还是 <code>NonfairSync</code>）。 <ul><li>在 <code>NonfairSync</code> 中，它会立即尝试获取锁，不管其他线程是否在等待。</li><li>在 <code>FairSync</code> 中，它会先检查队列，以确保没有其他线程在等待时间更长。</li></ul></li></ol><h5 id="释放锁的过程" tabindex="-1">释放锁的过程 <a class="header-anchor" href="#释放锁的过程" aria-label="Permalink to &quot;释放锁的过程&quot;">​</a></h5><ol><li>当线程调用 <code>unlock()</code> 方法时，实际上是调用 <code>Sync</code> 类的 <code>release(int)</code> 方法。</li><li><code>release(int)</code> 方法内部会调用 <code>tryRelease(int)</code> 方法，该方法检查当前线程是否是锁的持有者，并尝试将同步状态设置回 0。</li><li>如果同步状态成功设置回 0，表示锁已经被释放，等待队列中的其他线程可能会被唤醒并尝试获取锁。</li></ol><h5 id="aqs-中的等待队列" tabindex="-1">AQS 中的等待队列 <a class="header-anchor" href="#aqs-中的等待队列" aria-label="Permalink to &quot;AQS 中的等待队列&quot;">​</a></h5><p>AQS 使用一个内部的 FIFO 队列来管理那些无法获取到锁的线程。</p><p>每个节点代表一个线程。当一个线程无法获取到锁时，它会被包装成一个节点加入到队列的末尾。当锁被释放时，队列头部的节点会被唤醒并尝试再次获取锁。</p><h5 id="cas-在-aqs-中的使用" tabindex="-1">CAS 在 AQS 中的使用 <a class="header-anchor" href="#cas-在-aqs-中的使用" aria-label="Permalink to &quot;CAS 在 AQS 中的使用&quot;">​</a></h5><p>AQS 使用 CAS 操作来安全地修改同步状态。这是一种无锁的原子操作，可以保证即使在多个线程同时尝试修改状态时，同步状态的更新也是一致的。</p><blockquote><p>总结</p></blockquote><p><code>ReentrantLock</code> 的实现依赖于 AQS 的强大功能，提供了一种灵活且高效的方式来处理并发编程中的同步问题。</p><p>通过将锁的具体实现细节委托给 AQS，<code>ReentrantLock</code> 不仅提供了基本的锁功能，还支持如公平性/非公平性选择、条件变量、以及锁的可重入性等高级特性。</p><h3 id="_5、synchronized" tabindex="-1">5、synchronized <a class="header-anchor" href="#_5、synchronized" aria-label="Permalink to &quot;5、synchronized&quot;">​</a></h3><p>这部分内容的锁升级状态相关内容有必要阐述一下（无锁状态、偏向锁状态、轻量级锁状态、重量级锁状态）</p><h4 id="锁升级过程" tabindex="-1">锁升级过程 <a class="header-anchor" href="#锁升级过程" aria-label="Permalink to &quot;锁升级过程&quot;">​</a></h4><blockquote><p>说一下偏向锁、轻量级锁、重量级锁（锁升级过程）。</p></blockquote><p>在Java中，为了优化同步操作的性能，引入了偏向锁、轻量级锁和重量级锁的概念。</p><p>这些锁是对<code>synchronized</code>关键字的优化，旨在减少锁操作的开销。在不同竞争条件下，锁可以从偏向锁升级到轻量级锁，再升级到重量级锁。</p><p>偏向锁（Biased Locking）</p><ul><li><strong>目的</strong>：在只有一个线程访问同步块的情况下，减少不必要的锁竞争开销。</li><li><strong>原理</strong>：当锁被第一次获取时，它会将锁对象的头部信息标记为偏向模式，并记录获取它的线程ID。之后，该线程进入同步块时不需要再进行同步。</li><li><strong>升级条件</strong>：当有另一个线程尝试获取这个锁时，偏向锁会升级为轻量级锁。</li></ul><p>轻量级锁（Lightweight Locking）</p><ul><li><strong>目的</strong>：在无明显线程竞争的情况下，减少传统的锁机制（重量级锁）的性能消耗。</li><li><strong>原理</strong>：线程在获取锁时，会在栈帧中创建一个锁记录（Lock Record）空间，用于存储锁对象的头部信息。然后，尝试使用CAS（Compare And Swap）操作替换对象头部信息，将其指向锁记录。如果成功，线程获得锁；如果失败，表示其他线程竞争锁。</li><li><strong>升级条件</strong>：当多个线程竞争同一个锁时，轻量级锁会升级为重量级锁。</li></ul><p>重量级锁（Heavyweight Locking）</p><ul><li><strong>目的</strong>：在强竞争条件下，保证线程安全。</li><li><strong>原理</strong>：当锁处于重量级状态时，线程尝试获取锁失败，会进入阻塞状态。这需要操作系统的帮助，代价比轻量级锁和偏向锁要高。</li><li><strong>特点</strong>：重量级锁是最传统的同步方式，当有多个线程频繁竞争同一个锁时，使用重量级锁可以确保线程安全。</li></ul><p>锁升级过程</p><ol><li><strong>初始状态</strong>：新创建的锁对象默认是无锁状态。</li><li><strong>偏向锁</strong>：当第一个线程访问同步块时，锁会变为偏向锁。该线程后续进入同步块不需要真正的锁操作。</li><li><strong>轻量级锁</strong>：当有另一个线程尝试获取这个偏向锁时，如果持有偏向锁的线程不活跃，偏向锁可以撤销并升级为轻量级锁。</li><li><strong>重量级锁</strong>：如果轻量级锁的自旋失败（即多个线程竞争同一个锁），则升级为重量级锁。</li></ol><p>类比</p><p>可以将这些锁的升级过程类比为不同安全级别的门禁系统：</p><ul><li><strong>偏向锁</strong>：类似于一扇只允许一个特定员工进入的门。只要是这个员工，门会自动打开，无需任何验证。</li><li><strong>轻量级锁</strong>：类似于有一个简单的锁系统，员工需要刷卡（CAS操作）进入，如果门没有被其他人使用，这个过程很快。</li><li><strong>重量级锁</strong>：如果门经常被多人同时尝试使用，系统会升级到一个有保安的更复杂的门禁系统，来确保每次只有一个人进入。</li></ul><hr><p>参考:</p><ul><li><a href="https://blog.csdn.net/wang_yong_hui_1234/article/details/130165866" target="_blank" rel="noreferrer">https://blog.csdn.net/wang_yong_hui_1234/article/details/130165866</a></li><li><a href="https://www.bilibili.com/video/BV12K411G7Fg" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV12K411G7Fg</a></li><li><a href="https://javaguide.cn/java/concurrent/java-concurrent-questions-01.html" target="_blank" rel="noreferrer">https://javaguide.cn/java/concurrent/java-concurrent-questions-01.html</a></li><li><a href="https://www.bilibili.com/video/BV1z44y1X7BJ" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1z44y1X7BJ</a></li></ul>`,173)])])}const g=a(o,[["render",p]]);export{h as __pageData,g as default};
